export send
export receive
export become_leader

# The safety property:
invariant [safety] forall X: node, Y:node. leader(X) & leader(Y) -> X = Y  # at most one leader

invariant pending(idn(N), N) -> forall M. le(idn(M), idn(N))
invariant leader(N) -> forall M. (M ~= N -> ~pending(idn(M), M))

