after init  {
	holding(N) := true;
	collect(N, K, V, D) := false;

	proposed(N, K, V, D) := false;
	paid(N, K, V, D) := false;
	cancelled(N, K, V, D) := false;

	sig(N, K, V, D, S) := false;
}

