    require holding(n);
    require ~collect(n, k, v, d);
    require ~paid(n, k, v, d);

    holding(n) := false;
    collect(n, k, v, d) := true;
    sig(n, k, v, d, S) := false;
    proposed(n, k, v, d) := true;
}

