invariant forall T, X, Y, Z. (table(T,X,Y) & X ~= Y & table(T,Y,Z)) -> Z = Y
invariant forall T, X, Y, Z. (table(T,X,Y) & X ~= Y & table(T,Z,X)) -> Z = X

