invariant chosenAt(B,V) & ~le(B2,B) & isSafeAtPaxos(B2,V2) -> V2 = V
invariant msg_1b(A,B,MBAL,MVAL) -> le(MBAL, maxVBal(A))
invariant msg_1b(A,B,MBAL,MVAL) & maxVBal(A) = MBAL -> maxVal(A) = MVAL
invariant msg_2b(A,B,V) -> le(B, maxVBal(A))
