invariant tm_committed -> (forall R. (prepared(R) | committed(R)))
invariant tm_aborted -> (forall R. (working(R) | prepared(R) | aborted(R)))
invariant ~(tm_init & tm_committed)
invariant ~(tm_init & tm_aborted)
invariant ~(tm_committed & tm_aborted)
invariant tm_committed -> msg_commit
invariant tm_aborted -> msg_abort
invariant tm_init -> ~msg_commit & ~msg_abort
invariant tm_init | tm_committed | tm_aborted
invariant tm_prepared(R) -> prepared(R)
invariant msg_prepared(R) -> prepared(R)
invariant prepared(R) -> msg_prepared(R)
invariant ~(tm_prepared(R) & working(R))
invariant ~(tm_prepared(R) & aborted(R))
invariant ~(tm_prepared(R) & committed(R))
invariant ~(msg_commit & msg_abort)
invariant msg_commit -> tm_committed
invariant msg_abort -> tm_aborted
